algorithms.pseudocode:
function normalize(term t, rules R):
    while exists rule (l -> r) in R and subst s such that t = l[s]:
        t := r[s]
    return t

function check_confluence(rules R, test_terms T):
    for each pair of rules in R x R:
        for each overlap:
            cp = compute_critical_pair()
            if normalize(cp.left) != normalize(cp.right):
                return FAIL
    return CONFLUENT
